<?php use App\Core\Auth; $total=count($results['outgoing'])+count($results['incoming'])+count($results['classifications']); ?>
<section class="page-heading"><div><span class="eyebrow">PENCARIAN</span><h1>Pencarian PENA MAS</h1><p>Temukan surat dan kode klasifikasi dari satu tempat.</p></div></section>
<section class="panel global-search-page"><form method="get" action="/search" class="global-search-large"><?= ui_icon('search') ?><input name="q" value="<?= e($q) ?>" placeholder="Cari nomor surat, perihal, tujuan, asal, atau KKA..." autofocus><button class="btn btn-primary" type="submit">Cari</button></form><?php if($q===''):?><div class="empty-state"><span><?= ui_icon('search') ?></span><h3>Masukkan kata pencarian</h3><p>Contoh: nomor surat, “pajak”, nama tujuan, atau kode KKA.</p></div><?php elseif($total===0):?><div class="empty-state"><h3>Tidak ada hasil</h3><p>Coba kata yang lebih singkat atau berbeda.</p></div><?php else:?><div class="search-results-grid">
<?php if(Auth::canAccessOutgoing()):?><article class="search-group"><div class="search-group-head"><span><?= ui_icon('mail') ?></span><div><strong>Surat Keluar</strong><small><?= count($results['outgoing']) ?> hasil</small></div></div><?php foreach($results['outgoing'] as $r):$secret=in_array($r['sensitivity'],['RAHASIA','SANGAT_RAHASIA'],true);?><a href="/letters/<?= (int)$r['id'] ?>" class="search-result-item"><strong><?= e($r['letter_number']) ?></strong><span><?= $secret?'Detail terlindungi':e($r['subject']) ?></span><small><?= e(format_date_id($r['letter_date'])) ?> · <?= e($r['letter_type_name']) ?></small></a><?php endforeach;?><?php if(!$results['outgoing']):?><div class="search-empty-mini">Tidak ada surat keluar.</div><?php endif;?></article><?php endif; ?>
<?php if(Auth::canAccessIncoming()):?><article class="search-group"><div class="search-group-head"><span><?= ui_icon('archive') ?></span><div><strong>Surat Masuk</strong><small><?= count($results['incoming']) ?> hasil</small></div></div><?php foreach($results['incoming'] as $r):?><a href="/incoming/<?= (int)$r['id'] ?>" class="search-result-item"><strong><?= e($r['letter_number']) ?></strong><span><?= e($r['subject']) ?></span><small><?= e($r['origin']) ?> · <?= e(format_date_id($r['received_date'])) ?></small></a><?php endforeach;?><?php if(!$results['incoming']):?><div class="search-empty-mini">Tidak ada surat masuk.</div><?php endif;?></article><?php endif; ?>
<?php if(Auth::canAccessOutgoing()):?><article class="search-group"><div class="search-group-head"><span><?= ui_icon('archive') ?></span><div><strong>Klasifikasi KKA</strong><small><?= count($results['classifications']) ?> hasil</small></div></div><?php foreach($results['classifications'] as $r):?><a href="/admin/classifications?q=<?= urlencode($r['code']) ?>" class="search-result-item"><strong><?= e($r['group_code'].'.'.$r['code']) ?></strong><span><?= e($r['name']) ?></span><small><?= e($r['group_name']) ?></small></a><?php endforeach;?><?php if(!$results['classifications']):?><div class="search-empty-mini">Tidak ada kode KKA.</div><?php endif;?></article><?php endif; ?>
</div><?php endif;?></section>
